#[derive(Clone, Debug, PartialEq, Serialize, Deserialize, dsl::Mutations)]
#[mutations(snapshot = Iso16757Snapshot, diff = Iso16757Diff, schema = "s.norm.iso16757")]
pub enum Iso16757Mutation {
    ChangeExchangeProcess(change_exchange_process::mutation::ChangeExchangeProcess),
    UpdateScriptLimits(update_script_limits::mutation::UpdateScriptLimits),
    ReplacePartNumberRule(replace_part_number_rule::mutation::ReplacePartNumberRule),
    ChangePartNumberInput(change_part_number_input::mutation::ChangePartNumberInput),
    RemovePartNumberInput(remove_part_number_input::mutation::RemovePartNumberInput),
    ChangeSelectionClass(change_selection_class::mutation::ChangeSelectionClass),
    ChangeSelectionSeries(change_selection_series::mutation::ChangeSelectionSeries),
    AddSelectionConstraint(add_selection_constraint::mutation::AddSelectionConstraint),
    RemoveSelectionConstraint(remove_selection_constraint::mutation::RemoveSelectionConstraint),
    RenameCatalogue(rename_catalogue::mutation::RenameCatalogue),
    RenameManufacturer(rename_manufacturer::mutation::RenameManufacturer),
    CreateProductGroup(create_product_group::mutation::CreateProductGroup),
    DeleteProductGroup(delete_product_group::mutation::DeleteProductGroup),
    RenameProductGroup(rename_product_group::mutation::RenameProductGroup),
    CreateProduct(create_product::mutation::CreateProduct),
    DeleteProduct(delete_product::mutation::DeleteProduct),
    RenameProduct(rename_product::mutation::RenameProduct),
    CreatePropertyDefinition(create_property_definition::mutation::CreatePropertyDefinition),
    DeletePropertyDefinition(delete_property_definition::mutation::DeletePropertyDefinition),
    CreateSubject(create_subject::mutation::CreateSubject),
    DeleteSubject(delete_subject::mutation::DeleteSubject),
}

/// 🏷️ Every declared kind of [`Iso16757Mutation`], in `#[derive(dsl::Mutations)]`'s own declaration
/// order and spelling — the list `../../🧪️oracle/🔣️component.json` publishes as the `iso16757-1-any`
/// mutation catalog and `../../../../../🧪️tests/mutate-iso16757-1` registers its scenarios from. The
/// test platform never parses Rust, so [`kinds_catalog::kinds_match_the_enum_and_the_catalog`] below
/// is what keeps the enum, this const and the committed manifest from drifting apart.
pub const KINDS: &[&str] = &[
    "change-exchange-process",
    "update-script-limits",
    "replace-part-number-rule",
    "change-part-number-input",
    "remove-part-number-input",
    "change-selection-class",
    "change-selection-series",
    "add-selection-constraint",
    "remove-selection-constraint",
    "rename-catalogue",
    "rename-manufacturer",
    "create-product-group",
    "delete-product-group",
    "rename-product-group",
    "create-product",
    "delete-product",
    "rename-product",
    "create-property-definition",
    "delete-property-definition",
    "create-subject",
    "delete-subject",
];
//#endregion 🔖️Mutations

//#region 🔖️FromSnapshot
impl Iso16757Mutation {
    /// 📤️ Decomposes a whole-document replacement into the closed semantic vocabulary — the
    /// replacement for the banned whole-document-replace variant, used by `import_media`'s
    /// `"model:in"` port and the `set-snapshot` app command. Covers exactly this facet's migrated
    /// vocabulary (document-root scalars, catalogue/manufacturer naming, `product_groups`/`products`/
    /// `property_definitions`/`subjects` full CRUD, part-number inputs, selection constraints) — the
    /// deliberately-deferred collections (`product_classes`, `product_series`, `product_indexes`,
    /// `descriptive_objects`, dictionary `relationships`/`properties`/`controlled_lists`/
    /// `meta_subjects`, `geometry`) documented at this file's top have no mutation to decompose into
    /// and are therefore not represented by a whole-document replace either (same gap as `evaluate`/
    /// direct editing already has for those fields). `base` is required because every id-keyed
    /// collection here needs full remove/re-insert (highest BASE index first, so indices/positions
    /// stay valid mid-sequence).
    pub fn from_snapshot(base: &Iso16757Snapshot, target: &Iso16757Snapshot) -> Vec<Iso16757Mutation> {
        let mut mutations = Vec::new();
        mutations.push(Iso16757Mutation::RenameCatalogue(rename_catalogue::mutation::RenameCatalogue { new_name: target.catalogue.metadata.names.preferred.text.clone() }));
        mutations.push(Iso16757Mutation::RenameManufacturer(rename_manufacturer::mutation::RenameManufacturer { new_name: target.catalogue.manufacturer.names.preferred.text.clone() }));
        mutations.push(Iso16757Mutation::ChangeExchangeProcess(change_exchange_process::mutation::ChangeExchangeProcess { new_exchange_process: target.exchange_process.clone() }));
        mutations.push(Iso16757Mutation::UpdateScriptLimits(update_script_limits::mutation::UpdateScriptLimits {
            new_max_steps: target.script_limits.max_steps.clone(),
            new_max_recursion: target.script_limits.max_recursion.clone(),
            new_timeout_ms: target.script_limits.timeout_ms.clone(),
        }));
        mutations.push(Iso16757Mutation::ReplacePartNumberRule(replace_part_number_rule::mutation::ReplacePartNumberRule { new_rule: target.part_number_rule.clone() }));
        mutations.push(Iso16757Mutation::ChangeSelectionClass(change_selection_class::mutation::ChangeSelectionClass { new_class_id: target.selection.class_id.clone() }));
        mutations.push(Iso16757Mutation::ChangeSelectionSeries(change_selection_series::mutation::ChangeSelectionSeries { new_series_id: target.selection.series_id.clone() }));

        for key in base.part_number_inputs.keys() {
            if !target.part_number_inputs.contains_key(key) {
                mutations.push(Iso16757Mutation::RemovePartNumberInput(remove_part_number_input::mutation::RemovePartNumberInput { key: key.clone() }));
            }
        }
        for (key, value) in target.part_number_inputs.iter() {
            mutations.push(Iso16757Mutation::ChangePartNumberInput(change_part_number_input::mutation::ChangePartNumberInput { key: key.clone(), new_value: value.clone() }));
        }

        for index in (0..base.selection.constraints.len()).rev() {
            mutations.push(Iso16757Mutation::RemoveSelectionConstraint(remove_selection_constraint::mutation::RemoveSelectionConstraint { index }));
        }
        for constraint in target.selection.constraints.iter() {
            mutations.push(Iso16757Mutation::AddSelectionConstraint(add_selection_constraint::mutation::AddSelectionConstraint { constraint: constraint.clone() }));
        }

        for group in base.catalogue.product_groups.iter() {
            mutations.push(Iso16757Mutation::DeleteProductGroup(delete_product_group::mutation::DeleteProductGroup { id: group.id.clone() }));
        }
        for (index, group) in target.catalogue.product_groups.iter().enumerate() {
            mutations.push(Iso16757Mutation::CreateProductGroup(create_product_group::mutation::CreateProductGroup { product_group: group.clone(), index: Some(index) }));
        }

        for product in base.catalogue.products.iter() {
            mutations.push(Iso16757Mutation::DeleteProduct(delete_product::mutation::DeleteProduct { id: product.id.clone() }));
        }
        for (index, product) in target.catalogue.products.iter().enumerate() {
            mutations.push(Iso16757Mutation::CreateProduct(create_product::mutation::CreateProduct { product: product.clone(), index: Some(index) }));
        }

        for definition in base.catalogue.property_definitions.iter() {
            mutations.push(Iso16757Mutation::DeletePropertyDefinition(delete_property_definition::mutation::DeletePropertyDefinition { id: definition.id.clone() }));
        }
        for (index, definition) in target.catalogue.property_definitions.iter().enumerate() {
            mutations.push(Iso16757Mutation::CreatePropertyDefinition(create_property_definition::mutation::CreatePropertyDefinition { property_definition: definition.clone(), index: Some(index) }));
        }

        for subject in base.dictionary.subjects.iter() {
            mutations.push(Iso16757Mutation::DeleteSubject(delete_subject::mutation::DeleteSubject { id: subject.id.clone() }));
        }
        for (index, subject) in target.dictionary.subjects.iter().enumerate() {
            mutations.push(Iso16757Mutation::CreateSubject(create_subject::mutation::CreateSubject { subject: subject.clone(), index: Some(index) }));
        }

        mutations
    }
}
//#endregion 🔖️FromSnapshot

//#region 🧪️Tests
#[cfg(test)]
mod tests {
    use super::*;
    use crate::artifacts::iso16757::{part_1, part_4, part_5, Cardinality, LocalizedText, Names};
    use protocol::{Mutation, MutationDiff, SemanticMutation};

    fn round_trip(base: &Iso16757Snapshot, operation: &Iso16757Mutation) -> Iso16757Snapshot {
        let forward = operation.diff(base).diff().apply(base).expect("valid mutation diff");
        let backwards = operation.inverse(base);
        let mut restored = forward.clone();
        for back in &backwards {
            restored = back.diff(base).diff().apply(&restored).expect("valid mutation diff");
        }
        assert_eq!(&restored, base, "inverse must exactly restore the pre-operation fixture");
        forward
    }

    #[semio_framework_async_macros::async_test]
    fn change_exchange_process_round_trips() {
        let base = Iso16757Snapshot::reference_fixture();
        let mutation = Iso16757Mutation::ChangeExchangeProcess(change_exchange_process::mutation::ChangeExchangeProcess { new_exchange_process: part_5::ExchangeProcess::ProvideCatalogue });
        let after = round_trip(&base, &mutation);
        assert_eq!(after.exchange_process, part_5::ExchangeProcess::ProvideCatalogue);
    }

    #[semio_framework_async_macros::async_test]
    fn update_script_limits_round_trips() {
        let base = Iso16757Snapshot::reference_fixture();
        let mutation = Iso16757Mutation::UpdateScriptLimits(update_script_limits::mutation::UpdateScriptLimits { new_max_steps: 1, new_max_recursion: 2, new_timeout_ms: 3 });
        let after = round_trip(&base, &mutation);
        assert_eq!(after.script_limits, part_5::ScriptLimits { max_steps: 1, max_recursion: 2, timeout_ms: 3 });
    }

    #[semio_framework_async_macros::async_test]
    fn change_and_remove_part_number_input_round_trip() {
        let base = Iso16757Snapshot::reference_fixture();
        let change = Iso16757Mutation::ChangePartNumberInput(change_part_number_input::mutation::ChangePartNumberInput { key: "new-key".into(), new_value: crate::artifacts::iso16757::CatalogueValue::Decimal { value: 7.0 } });
        let after_change = round_trip(&base, &change);
        assert_eq!(after_change.part_number_inputs.get("new-key"), Some(&crate::artifacts::iso16757::CatalogueValue::Decimal { value: 7.0 }));

        let remove = Iso16757Mutation::RemovePartNumberInput(remove_part_number_input::mutation::RemovePartNumberInput { key: "dn".into() });
        let after_remove = round_trip(&base, &remove);
        assert!(!after_remove.part_number_inputs.contains_key("dn"));
    }

    #[semio_framework_async_macros::async_test]
    fn change_part_number_input_undo_of_a_fresh_key_is_remove() {
        let base = Iso16757Snapshot::reference_fixture();
        let change = Iso16757Mutation::ChangePartNumberInput(change_part_number_input::mutation::ChangePartNumberInput { key: "fresh".into(), new_value: crate::artifacts::iso16757::CatalogueValue::Boolean { value: true } });
        let undo = change.inverse(&base);
        assert_eq!(undo, vec![Iso16757Mutation::RemovePartNumberInput(remove_part_number_input::mutation::RemovePartNumberInput { key: "fresh".into() })]);
    }

    #[semio_framework_async_macros::async_test]
    fn selection_class_and_constraints_round_trip() {
        let base = Iso16757Snapshot::reference_fixture();
        let change_class = Iso16757Mutation::ChangeSelectionClass(change_selection_class::mutation::ChangeSelectionClass { new_class_id: "class.other".into() });
        let after = round_trip(&base, &change_class);
        assert_eq!(after.selection.class_id, "class.other");

        let constraint = part_1::SelectionConstraint { property_id: "prop.other".into(), operator: part_1::ConstraintOperator::NotEqual, value: crate::artifacts::iso16757::CatalogueValue::Text { value: "x".into() } };
        let add = Iso16757Mutation::AddSelectionConstraint(add_selection_constraint::mutation::AddSelectionConstraint { constraint });
        let after_add = round_trip(&base, &add);
        assert_eq!(after_add.selection.constraints.len(), base.selection.constraints.len() + 1);

        let remove = Iso16757Mutation::RemoveSelectionConstraint(remove_selection_constraint::mutation::RemoveSelectionConstraint { index: 0 });
        let after_remove = round_trip(&base, &remove);
        assert_eq!(after_remove.selection.constraints.len(), base.selection.constraints.len() - 1);
    }

    #[semio_framework_async_macros::async_test]
    fn rename_catalogue_and_manufacturer_round_trip() {
        let base = Iso16757Snapshot::reference_fixture();
        let rename_catalogue = Iso16757Mutation::RenameCatalogue(rename_catalogue::mutation::RenameCatalogue { new_name: "Renamed Catalogue".into() });
        let after = round_trip(&base, &rename_catalogue);
        assert_eq!(after.catalogue.metadata.names.preferred.text, "Renamed Catalogue");

        let rename_manufacturer = Iso16757Mutation::RenameManufacturer(rename_manufacturer::mutation::RenameManufacturer { new_name: "Renamed Mfg".into() });
        let after = round_trip(&base, &rename_manufacturer);
        assert_eq!(after.catalogue.manufacturer.names.preferred.text, "Renamed Mfg");
    }

    #[semio_framework_async_macros::async_test]
    fn create_then_delete_product_group_round_trips() {
        let base = Iso16757Snapshot::reference_fixture();
        let product_group = part_1::ProductGroup { id: "group.new".into(), names: Names { preferred: LocalizedText { locale: "en".into(), text: "New Group".into() }, short_name: None, alternatives: Vec::new() }, dictionary_subject_id: None };
        let create = Iso16757Mutation::CreateProductGroup(create_product_group::mutation::CreateProductGroup { product_group: product_group.clone(), index: None });
        let after_create = round_trip(&base, &create);
        assert!(after_create.catalogue.product_groups.iter().any(|group| group.id == "group.new"));

        let undo = create.inverse(&base);
        assert_eq!(undo, vec![Iso16757Mutation::DeleteProductGroup(delete_product_group::mutation::DeleteProductGroup { id: "group.new".into() })]);

        let rename = Iso16757Mutation::RenameProductGroup(rename_product_group::mutation::RenameProductGroup { id: "group.new".into(), new_name: "Renamed".into() });
        let after_rename = round_trip(&after_create, &rename);
        assert_eq!(after_rename.catalogue.product_groups.iter().find(|group| group.id == "group.new").unwrap().names.preferred.text, "Renamed");

        let delete = Iso16757Mutation::DeleteProductGroup(delete_product_group::mutation::DeleteProductGroup { id: "group.valves".into() });
        let after_delete = round_trip(&base, &delete);
        assert!(!after_delete.catalogue.product_groups.iter().any(|group| group.id == "group.valves"));
    }

    #[semio_framework_async_macros::async_test]
    fn delete_product_group_of_a_missing_id_has_an_empty_inverse() {
        let base = Iso16757Snapshot::reference_fixture();
        let delete = Iso16757Mutation::DeleteProductGroup(delete_product_group::mutation::DeleteProductGroup { id: "nope".into() });
        assert!(delete.inverse(&base).is_empty(), "deleting an absent id has nothing to undo");
    }

    #[semio_framework_async_macros::async_test]
    fn create_rename_delete_product_round_trips() {
        let base = Iso16757Snapshot::reference_fixture();
        let product = part_1::Product {
            id: "product.new".into(),
            series_id: "series.cv".into(),
            names: Names { preferred: LocalizedText { locale: "en".into(), text: "New Product".into() }, short_name: None, alternatives: Vec::new() },
            parameter_domains: Vec::new(),
            variants: Vec::new(),
            static_properties: Vec::new(),
        };
        let create = Iso16757Mutation::CreateProduct(create_product::mutation::CreateProduct { product: product.clone(), index: None });
        let after_create = round_trip(&base, &create);
        assert!(after_create.catalogue.products.iter().any(|p| p.id == "product.new"));

        let rename = Iso16757Mutation::RenameProduct(rename_product::mutation::RenameProduct { id: "product.new".into(), new_name: "Renamed Product".into() });
        let after_rename = round_trip(&after_create, &rename);
        assert_eq!(after_rename.catalogue.products.iter().find(|p| p.id == "product.new").unwrap().names.preferred.text, "Renamed Product");

        let delete = Iso16757Mutation::DeleteProduct(delete_product::mutation::DeleteProduct { id: "product.cv".into() });
        let after_delete = round_trip(&base, &delete);
        assert!(!after_delete.catalogue.products.iter().any(|p| p.id == "product.cv"));
        let undo = delete.inverse(&base);
        assert_eq!(undo.len(), 1);
    }

    #[semio_framework_async_macros::async_test]
    fn create_then_delete_property_definition_round_trips() {
        let base = Iso16757Snapshot::reference_fixture();
        let definition = part_1::PropertyDefinition {
            id: "prop.new".into(),
            names: Names { preferred: LocalizedText { locale: "en".into(), text: "New Prop".into() }, short_name: None, alternatives: Vec::new() },
            data_type: "text".into(),
            unit: None,
            cardinality: Cardinality::optional(),
            kind: part_1::PropertyKind::Static,
            dictionary_property_id: None,
        };
        let create = Iso16757Mutation::CreatePropertyDefinition(create_property_definition::mutation::CreatePropertyDefinition { property_definition: definition, index: None });
        let after_create = round_trip(&base, &create);
        assert!(after_create.catalogue.property_definitions.iter().any(|d| d.id == "prop.new"));

        let delete = Iso16757Mutation::DeletePropertyDefinition(delete_property_definition::mutation::DeletePropertyDefinition { id: "prop.new".into() });
        let after_delete = round_trip(&after_create, &delete);
        assert!(!after_delete.catalogue.property_definitions.iter().any(|d| d.id == "prop.new"));
    }

    #[semio_framework_async_macros::async_test]
    fn create_then_delete_subject_round_trips() {
        let base = Iso16757Snapshot::reference_fixture();
        let subject = part_4::Subject {
            id: "subject.new".into(),
            kind: part_4::SubjectKind::ProductClass,
            names: Names { preferred: LocalizedText { locale: "en".into(), text: "New Subject".into() }, short_name: None, alternatives: Vec::new() },
            definition: LocalizedText { locale: "en".into(), text: "A new subject".into() },
            parent_id: None,
        };
        let create = Iso16757Mutation::CreateSubject(create_subject::mutation::CreateSubject { subject: subject.clone(), index: None });
        let after_create = round_trip(&base, &create);
        assert!(after_create.dictionary.subjects.iter().any(|s| s.id == "subject.new"));

        let delete = Iso16757Mutation::DeleteSubject(delete_subject::mutation::DeleteSubject { id: "subject.new".into() });
        let after_delete = round_trip(&after_create, &delete);
        assert!(!after_delete.dictionary.subjects.iter().any(|s| s.id == "subject.new"));

        let delete_missing = Iso16757Mutation::DeleteSubject(delete_subject::mutation::DeleteSubject { id: "nope".into() });
        assert!(delete_missing.inverse(&base).is_empty());
    }

    #[semio_framework_async_macros::async_test]
    fn semantic_kinds_cover_every_variant() {
        assert_eq!(Iso16757Mutation::kinds().len(), 21);
        let mutation = Iso16757Mutation::RenameCatalogue(rename_catalogue::mutation::RenameCatalogue { new_name: "x".into() });
        assert_eq!(mutation.semantics().kind, "rename-catalogue");
        assert_eq!(mutation.semantics().record, "RenamedCatalogue");
    }
}
